# November 24, 2026: Denver, Colorado (region co), worked from a list of buildings named in a video about the city.
# The video was used only as a list of names; every fact below comes from a source opened while writing: Wikipedia as raw
# text (with the downtown Denver Register list), National Register nomination forms from NPGallery, Westword (May 6, 2024)
# on the El Jebel building, and the pages of Colorado Parks and Wildlife, the churches and Denver Union Station.
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
NP='https://npgallery.nps.gov/NRHP/GetAsset/NRHP/'
BATCH={'key':'denver_ejjs','label':'Denver, Colorado: downtown and Capitol Hill','added':'2026-11-24 01:33'}
PLACES=[
N('daniels-fisher-tower-denver','Daniels & Fisher Tower','Denver','co','civic','standing',39.74813,-104.99561,'exact','view','walk','','1910',
  'The clock tower of the Daniels & Fisher department store, built in 1910 to designs by Frederick Sterner and modelled on the campanile of St. Mark\'s in Venice. At 325 feet it was then the tallest building between the Mississippi and California. A 5,500-pound bell went into its top floors in 1911. May Company bought the store in 1958; when the store was pulled down, about 1971, the tower alone was saved, and in 1981 it was made into offices and homes. Listed on the National Register in 1969.',
  'Twenty floors with a clock face on each side, standing alone where the store once was, at 16th and Arapahoe streets on the 16th Street Mall. Seen from the street; interior not checked.',
  'The store came down and its Venetian clock tower was kept.',
  'Privately owned offices and homes (Wikipedia). At 1601 Arapahoe Street, on the 16th Street Mall: view from the street. Paid parking garages and meters downtown.',
  [W('Daniels & Fisher Tower')],brick='?'),
N('boston-building-denver','Boston Building','Denver','co','civic','standing',39.746944,-104.991667,'site','view','walk','','1890',
  'An eight-story office block at the southeast corner of 17th and Champa streets, begun in 1890 on the site of Wolfe Hall, an Episcopal school for girls of 1867 that was sold in 1888 and pulled down in 1889. Its nomination form calls it a mix of Renaissance Revival and Richardsonian Romanesque, with arcaded windows like those of H. H. Richardson\'s Field building in Chicago. Listed on the National Register in 1978.',
  'The whole building is faced with red Greenlee sandstone quarried near Manitou Springs, and its carving is cut from the same stone; the form (1978) says the rough lower blocks were later smoothed, the cornice with carved heads is gone and the entrance was modernized in 1959. Present use and owner not checked: view from the street.',
  'An 1890 red-sandstone office block on the site of a girls\' school.',
  'At 828 17th Street. Privately owned: view from the street. Paid parking garages and meters downtown.',
  [L('National Register nomination form (1978)',NP+'78000841_text')],brick='no'),
N('brown-palace-hotel-denver','Brown Palace Hotel','Denver','co','hotel','standing',39.74411,-104.98787,'exact','open','walk','hotels','1892',
  'A triangular hotel of sandstone and red granite built in 1892 for Henry C. Brown, who had homesteaded Capitol Hill, to designs by Frank Edbrooke; Wikipedia counts it the finest surviving example of his work and one of the first atrium hotels. Scientific American called it one of America\'s first fireproof buildings. It has never closed and is now run as part of Marriott\'s Autograph Collection. Listed on the National Register in 1970.',
  'The atrium lobby, with Allen Tupper True\'s two murals of 1937 (Stage Coach and Airplane Travel) and a placard marking the 1959 lobby meeting that led to the American Football League. A working hotel; whether the lobby is open to people who are not guests, and any history tours, were not checked.',
  'A triangular 1892 hotel round a nine-story atrium.',
  'Working hotel at 321 17th Street; the main entrance is on Tremont Place. The hotel\'s own site gave no visiting hours. Paid parking garages and meters downtown.',
  [W('Brown Palace Hotel (Denver)'),L('The Brown Palace','https://www.brownpalace.com/')],brick='no',hours='?'),
N('union-station-denver','Denver Union Station','Denver','co','rail','standing',39.75345,-104.99982,'site','open','walk','stations','1881; centre rebuilt 1914',
  'Denver\'s main station, at 17th and Wynkoop streets. The first Union Depot opened here in 1881 for four railroads; fire gutted it in 1894 and it was rebuilt, and the central part was taken down and replaced by the present granite and terracotta hall, opened in 1914. The wings keep the Romanesque stonework of 1881. After a renovation it reopened in 2014 as the Crawford Hotel, shops and restaurants over a working station for Amtrak, light rail and buses. Listed on the National Register in 1974.',
  'The Great Hall serves as hotel lobby, train waiting room and public space (Wikipedia). Look for the columbine, Colorado\'s state flower, carved in the stonework of the older wings.',
  'Built for four railroads in 1881, rebuilt twice, still a working station.',
  'A working station and hotel at 1701 Wynkoop Street, managed as Denver Union Station; the Great Hall is a public waiting room. No opening hours were given on the station\'s own pages. Reached by light rail and train; paid parking nearby.',
  [W('Denver Union Station'),L('Denver Union Station: about','https://www.denverunionstation.com/about/')],brick='no',hours='?'),
N('kittredge-building-denver','Kittredge Building','Denver','co','civic','standing',39.74422,-104.99047,'exact','view','walk','','1889–1891',
  'A seven-story Richardsonian Romanesque office block built in 1889 to 1891 for Charles M. Kittredge. Its nomination form counts it among the first big office buildings on 16th Street. Listed on the National Register in 1977.',
  'Heavily rusticated granite and volcanic stone, a big Romanesque arch over the 16th Street door springing from short columns, rows of arched windows and turrets at the roof line; both street fronts look alike (nomination form). Interior not checked.',
  'An 1891 stone office block with turrets on the 16th Street Mall.',
  'At 511 16th Street, on the 16th Street Mall. Privately owned: view from the street. Paid parking downtown.',
  [L('National Register nomination form (1977)',NP+'77000368_text')],brick='no'),
N('equitable-building-denver','Equitable Building','Denver','co','civic','standing',39.74632,-104.99196,'exact','view','walk','','1892',
  'A nine-story steel-framed office block of 1892, designed by Andrews, Jaques & Rantoul, and the tallest building in Denver until the Daniels & Fisher Tower passed it in 1911. It cost $1.5 million and was built to look after itself: its Register listing says an artesian well in the basement ran its eight elevators. Listed on the National Register in 1978.',
  'Italian Renaissance Revival, with rows of arched windows and carved granite. Interior not checked.',
  'Denver\'s tallest building from 1892 to 1911.',
  'At 730 17th Street. Privately owned offices: view from the street. Paid parking downtown.',
  [W('Equitable Building (Denver)')],brick='?'),
N('denver-dry-goods-building','Denver Dry Goods Company Building','Denver','co','civic','standing',39.74509,-104.99283,'exact','view','walk','','1889',
  'The flagship store of the Denver Dry Goods Company, built in 1889 and enlarged in 1898, 1906 and 1924; a 1916 postcard called it the largest store in the Central West, 400 feet long with seven acres of floors. May Company took it over in 1986, and the building was made into apartments in 1994.',
  'A block-long store front on California Street between 15th and 16th streets, with a covered entrance. Now apartments: view from the street.',
  'Once billed as the biggest store in the Central West.',
  'At 1565 California Street. Apartments, privately owned: view from the street. Paid parking downtown.',
  [W('Denver Dry Goods Company Building')],brick='?'),
N('immaculate-conception-cathedral-denver','Cathedral Basilica of the Immaculate Conception','Denver','co','worship','standing',39.74044,-104.98198,'exact','open','walk','','1901–1911',
  'The cathedral of the Catholic Archdiocese of Denver, begun in 1901, finished in 1911 and dedicated in 1912, of Indiana limestone and granite from Gunnison, Colorado. It was made a minor basilica in 1979 and its outer walls and carvings were repaired from 2016. Listed on the National Register in 1975.',
  'Inside: 75 stained glass windows with 20,000 pieces of glass, made by the Royal Bavarian Art Institute in Munich; a rose window of seven angels over the choir loft; altar, pulpit, statues and bishop\'s chair of Carrara marble, and steps and pillar bases of Yule marble from Marble, Colorado (Wikipedia).',
  'Bavarian stained glass and Colorado marble in a working cathedral.',
  'Active cathedral at 401 East Colfax Avenue at Logan Street. Opening and Mass times from the cathedral\'s own page. Street parking and paid lots nearby.',
  [W('Cathedral Basilica of the Immaculate Conception (Denver)'),L('The cathedral\'s own page','https://denvercathedral.org/')],brick='no',
  hours='Church open Monday to Friday 6:45 a.m. to 6:45 p.m., Saturday 6:45 a.m. to 6 p.m., Sunday 8 a.m. to 8 p.m.; Sunday Mass 8:30, 10:30, 12:30, 6:30'),
N('central-presbyterian-denver','Central Presbyterian Church','Denver','co','worship','standing',39.74290,-104.98447,'exact','open','walk','','1891–1892',
  'Built in 1891 to 1892 to designs by Frank E. Edbrooke, in the Richardsonian Romanesque style, and counted among the three best buildings he designed. The congregation grew out of Denver\'s First Presbyterian Church of 1860 and took this name in 1874. Recorded by the Historic American Buildings Survey in 1969; listed on the National Register in 1974.',
  'A huge, nearly square church of Colorado sandstone laid in horizontal bands, with crossing gables and a tower with long, thin lantern openings under ogee arches (Wikipedia). Interior not checked.',
  'Edbrooke\'s great red-stone church.',
  'Active church at 1660 Sherman Street. Service times from the church\'s own page; it says parking in the lot across Sherman Street is free on Sundays from 8:30 a.m. to 1:30 p.m. only (enter from 16th Avenue) and is ticketed at other times.',
  [W('Central Presbyterian Church (Denver)'),L('Central Presbyterian: new here','https://centraldenver.com/about/new-here')],brick='no',
  hours='Sunday service 10 a.m.'),
N('trinity-methodist-denver','Trinity United Methodist Church','Denver','co','worship','standing',39.74510,-104.98700,'exact','open','walk','','1887',
  'A Gothic Revival church at 18th Avenue and Broadway, built in 1887 to designs by Robert S. Roeschlaub, assisted by Frederick A. Hale, and extended in the same style in 1926. Its auditorium seats 1,200 and was the largest venue in Denver when it was built. Listed on the National Register in 1970.',
  'A 181-foot spire, several stained glass windows and a pipe organ of 4,290 pipes built in the Roosevelt style (Wikipedia).',
  'A stone spire of 1887 and a 4,000-pipe organ.',
  'Active church at 1820 Broadway. Service time from the church\'s own page, which says parking in its north and east lots and garage is free on Sundays until 2 p.m. (bring the garage ticket in for validation).',
  [W('Trinity United Methodist Church (Denver)'),L('Trinity United Methodist Church','https://trinityumc.org/')],brick='?',
  hours='Sunday service 10:30 a.m.'),
N('st-johns-cathedral-denver','Saint John\'s Cathedral (St. John in the Wilderness)','Denver','co','worship','standing',39.73828,-104.97815,'site','open','walk','','1908–1911',
  'The cathedral of the Episcopal Diocese of Colorado. The parish began in 1860 and was called "in the Wilderness" because the nearest Episcopal parish was 700 miles away; its first cathedral, at 20th and Welton, burned in 1903. The present one, designed by Tracy and Swartwout of New York, was begun in 1908 and first used in 1911. Only the limestone nave of the plan was built, with a chancel of brick meant to be temporary. Listed on the National Register in 1975.',
  'Stained glass from Charles Connick\'s studio (Wikipedia).',
  'A cathedral named for a wilderness 700 miles from the next parish.',
  'Active cathedral at 1350 North Washington Street. Service times from the cathedral\'s own page. Street parking.',
  [W('Cathedral of St. John in the Wilderness'),L('Saint John\'s Cathedral: worship','https://www.sjcathedral.org/worship')],brick='?',
  hours='Sunday services 8 a.m., 10:30 a.m. and 5 p.m.'),
N('st-marks-church-denver','St. Mark\'s Parish Church (The Church nightclub)','Denver','co','worship','standing',39.73519,-104.98553,'site','view','walk','','1889',
  'An Episcopal church built in 1889 to designs by Lang and Pugh. Its castellated corner tower failed in the 1950s, taking a small carillon with it, and was not rebuilt. The congregation moved to Washington Park in 1987; the building was bought in 1994 and has been a nightclub since 1996. Listed on the National Register in 1975.',
  'A Gothic stone church with a buttress where the tower turret stood, and aisles with stained glass windows in sets of three (nomination form). Now a nightclub for dance-music events: look from the street.',
  'A Gothic church that has been a nightclub since 1996.',
  'At 1160 Lincoln Street. Privately owned nightclub: view from the street. Street parking.',
  [W('The Church Nightclub'),L('National Register nomination form (1975)',NP+'75000514_text')],brick='?'),
N('el-jebel-shrine-denver','Mosque of the El Jebel Shrine','Denver','co','civic','standing',39.74463,-104.98449,'exact','view','walk','','1907',
  'A Moorish-style meeting hall built in 1907 for Denver\'s El Jebel Shriners, never a mosque in the Islamic sense. The Shriners sold it in 1924 to the Scottish Rite Masons, and from 1995 it was a catering and events hall until 2012. Westword reported in May 2024 that it stood empty from 2012 to 2023, that the owner was in foreclosure, and that a company was cleaning it up to rent for events; a conservation easement held by Historic Denver since 2003 requires any owner to keep the building. Listed on the National Register in 1997.',
  'Red brick walls with onion-domed turrets outside (photograph on Wikimedia Commons). Inside, per Westword, a ballroom in the style of the Alhambra over the second and third floors, with a scalloped ceiling, a wraparound balcony and stained glass and painted doors. Open only for events: look from the street.',
  'A Shriners\' "mosque" of 1907 with an Alhambra ballroom.',
  'At 1770 Sherman Street. Privately owned and used for events: view from the street. Street parking.',
  [W('Sherman Street Event Center'),L('National Register nomination form (1997)',NP+'97001235_text'),L('Westword: After a decade, Denver\'s El Jebel building is ready for the public (2024)','https://www.westword.com/news/inside-el-jebel-building-classic-denver-architecture-20604277')],brick='yes'),
N('paramount-theatre-denver','Paramount Theatre','Denver','co','civic','standing',39.74425,-104.99016,'exact','open','walk','','1930',
  'A movie palace opened in 1930 for the Paramount-Publix circuit, designed by Rapp and Rapp of Chicago, with decoration by Vincent Mondo and murals by Louis Grell. The front on Glenarm Place, now the main entrance, is an Art Deco take on Gothic by Temple H. Buell in cast concrete and white terra cotta. By 1978 it was the last movie palace left in Denver; it is now a concert hall of 1,870 seats. Listed on the National Register in 1980.',
  'The white terra cotta front on Glenarm Place, and inside a Wurlitzer organ (Wikipedia). Inside on show nights only.',
  'Denver\'s last movie palace, now a concert hall.',
  'At 1621 Glenarm Place, by the 16th Street Mall. Open for ticketed shows; the theatre\'s own page lists them. Paid parking downtown.',
  [W('Paramount Theatre (Denver)'),L('Paramount Theatre','https://www.paramountdenver.com/')],brick='no',hours='?'),
N('gas-electric-building-denver','Denver Gas & Electric Building','Denver','co','civic','standing',39.74585,-104.99565,'exact','view','walk','','1910',
  'A ten-story building completed in 1910 for the Denver Gas & Electric Company, designed by Harry W. J. Edbrooke. It has also been the Public Service Building and the Insurance Exchange Building, and is now an internet exchange. Listed on the National Register in 1978.',
  'Its front is studded with 13,000 electric light bulbs (Wikipedia). OpenStreetMap names it the Insurance Exchange Building, 910 15th Street. Interior not checked.',
  'The power company\'s office, outlined in 13,000 bulbs.',
  'At 910 15th Street, at Champa Street. Privately owned: view from the street. Paid parking downtown.',
  [W('Denver Gas & Electric Building')],brick='?'),
N('byron-white-courthouse-denver','Byron White U.S. Courthouse (old post office)','Denver','co','civic','standing',39.74867,-104.98994,'site','view','walk','','1910–1916',
  'Denver\'s post office and federal courthouse, built in 1910 to 1916 to designs by Egerton Swartwout of Tracy, Swartwout and Litchfield, after the 1893 post office was found too small. It is now the seat of the U.S. Court of Appeals for the Tenth Circuit, and was renamed in 1994 for Supreme Court Justice Byron White. Listed on the National Register in 1973.',
  'Neoclassical, clad in Yule marble from Colorado, the stone of the Lincoln Memorial; marble seats with inscriptions, and Rocky Mountain sheep carved by Gladys Caldwell Fisher at the southwest entrance. Inside, per Wikipedia: a terrazzo lobby with a vaulted ceiling, and a courtroom with its original gold-trimmed velvet drapery.',
  'A marble post office of 1916, now a federal appeals court.',
  'A working federal courthouse at 18th and Stout streets: the outside is seen from the street; going in means passing court security, and visiting rules were not checked. Paid parking downtown.',
  [W('Byron White United States Courthouse')],brick='no'),
N('firefighters-museum-denver','Denver Firefighters Museum (Fire Station No. 1)','Denver','co','civic','standing',39.74066,-104.99243,'exact','open','walk','','1909',
  'Fire Station No. 1, built in 1909 for $20,000 to designs by Glen W. Huntington. It replaced the first Station One at 15th Street and Broadway, which was taken down that year for the Pioneer Monument. It has been the Denver Firefighters Museum, a nonprofit, since 1978. A Denver landmark from 1974, listed on the National Register in 1979.',
  'Four galleries on Denver\'s fire history, and the firemen\'s old living quarters: dormitory, officers\' rooms, locker room and family room (Wikipedia).',
  'A 1909 fire station with its firemen\'s quarters kept as they were.',
  'Museum at 1326 Tremont Place; admission charged. Hours not checked: the museum\'s own site could not be opened when this was written. Paid parking downtown.',
  [W('Denver Firefighters Museum'),L('Denver Firefighters Museum: plan your visit','https://denverfirefightersmuseum.org/plan-your-visit')],brick='?',hours='?'),
N('castlewood-dam-ruins','Castlewood Canyon Dam ruins','Franktown','co','water','ruins',39.34126,-104.75699,'site','public','hike','','1890–1933',
  'A dam built across Cherry Creek in Castlewood Canyon in 1890 to turn the flood-prone creek into a source of irrigation water. It was known for leaking, and at 1 a.m. on August 3, 1933, after heavy rain, it gave way, sending a 15-foot wall of water down Cherry Creek to Denver, about 15 miles away. The canyon, the dam and its old reservoir became part of Castlewood Canyon State Park in the 1970s.',
  'The broken remains of the dam in the canyon (Colorado Parks and Wildlife). The park also holds the ruin of the Lucas homestead and the historic Cherry Creek Bridge.',
  'The leaky dam that burst in 1933 and flooded Denver.',
  'Castlewood Canyon State Park, Colorado Parks and Wildlife. Daily vehicle pass $10 to $15, or $4 a person. Main entrance off Highway 83, five miles south of Franktown, with the visitor center; the west entrance off Castlewood Canyon Road from Highway 86 has gravel lots and vault toilets. Park sunrise to sunset; visitor center Wednesday to Sunday 9 a.m. to 5 p.m. Stay on the trails.',
  [W('Castlewood Canyon State Park'),L('Colorado Parks and Wildlife: Castlewood Canyon State Park','https://cpw.state.co.us/state-parks/castlewood-canyon-state-park')],
  th=[39.34912,-104.76434],thn='Falls Spur Trail lot, west side of the park',brick='?',
  hours='Park sunrise to sunset; visitor center Wednesday to Sunday 9 a.m. to 5 p.m.'),
N('westminster-castle','Westminster Castle (Westminster University)','Westminster','co','inst','standing',39.84727,-105.03209,'exact','view','drive','','1893',
  'The main building of a Presbyterian university planned in 1890 by Henry T. Mayham on Crown Point. E. B. Gregory laid out the first design; Stanford White finished it in red sandstone from the Red Rocks and Manitou area, a Richardsonian Romanesque front 160 feet long with a 175-foot tower. It was finished in 1893, but the Panic of 1893 kept it empty until classes began in 1908; the university closed in 1917. In 1920 Alma Bridwell White\'s Pillar of Fire Church bought it, and Belleview Christian Schools still use the campus. Listed on the National Register as Westminster University.',
  'A red sandstone castle with a tall tower on a rise near 83rd Avenue and Federal Boulevard. A school building: look from the road.',
  'A university building finished in 1893 that waited 15 years for its students.',
  'Owned by the Pillar of Fire Church and used by Belleview Christian Schools (Wikipedia). At 3455 West 83rd Avenue, Westminster: view from the road; do not enter the school grounds.',
  [W('Westminster Castle')],brick='no'),
]
